// Single-source BFS on adjacency list
void bfs(int src, List<List<Integer>> adj, int n) {
    int[] dist = new int[n];
    Arrays.fill(dist, -1);
    Queue<Integer> q = new ArrayDeque<>();
    q.offer(src);
    dist[src] = 0;
    while (!q.isEmpty()) {
        int u = q.poll();
        for (int v : adj.get(u)) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.offer(v);
            }
        }
    }
}

// Grid BFS (4-directional)
void gridBFS(int[][] grid, int sr, int sc) {
    int m = grid.length, n = grid[0].length;
    int[] dx = {0, 0, 1, -1};
    int[] dy = {1, -1, 0, 0};
    Queue<int[]> q = new ArrayDeque<>();
    q.offer(new int[]{sr, sc});
    grid[sr][sc] = -1; // mark visited in-place
    while (!q.isEmpty()) {
        int[] cur = q.poll();
        int x = cur[0], y = cur[1];
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] == 1) {
                grid[nx][ny] = -1; // mark visited immediately
                q.offer(new int[]{nx, ny});
            }
        }
    }
}

// Level-by-level BFS (returns number of levels)
int bfsLevels(int src, List<List<Integer>> adj, int n) {
    boolean[] visited = new boolean[n];
    Queue<Integer> q = new ArrayDeque<>();
    q.offer(src);
    visited[src] = true;
    int levels = 0;
    while (!q.isEmpty()) {
        int size = q.size(); // snapshot of current level's size
        for (int i = 0; i < size; i++) {
            int u = q.poll();
            for (int v : adj.get(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.offer(v);
                }
            }
        }
        levels++;
    }
    return levels - 1; // 0-indexed levels
}

