class Solution {
    public int shortestPathBinaryMatrix(int[][] grid) {
        int n = grid.length;
        if (grid[0][0] == 1 || grid[n-1][n-1] == 1) return -1;
        // 8 directions: all combinations of -1, 0, 1 except (0,0)
        int[] dx = {-1,-1,-1, 0, 0, 1, 1, 1};
        int[] dy = {-1, 0, 1,-1, 1,-1, 0, 1};
        // Queue stores {row, col, distance}
        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{0, 0, 1});
        grid[0][0] = 1; // mark visited by blocking
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1], dist = cur[2];
            if (x == n-1 && y == n-1) return dist;
            for (int d = 0; d < 8; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx >= 0 && nx < n && ny >= 0 && ny < n
                    && grid[nx][ny] == 0) {
                    grid[nx][ny] = 1; // mark visited before enqueue
                    q.offer(new int[]{nx, ny, dist + 1});
                }
            }
        }
        return -1;
    }
}

class Solution {
    public int orangesRotting(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        Queue<int[]> q = new ArrayDeque<>();
        int fresh = 0;
        // Seed the queue with all initially rotten oranges
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 2) q.offer(new int[]{i, j});
                else if (grid[i][j] == 1) fresh++;
            }
        }
        if (fresh == 0) return 0; // no fresh oranges at start
        int[] dx = {0, 0, 1, -1};
        int[] dy = {1, -1, 0, 0};
        int minutes = 0;
        while (!q.isEmpty()) {
            int size = q.size(); // process one full level (= 1 minute)
            minutes++;
            for (int k = 0; k < size; k++) {
                int[] cur = q.poll();
                for (int d = 0; d < 4; d++) {
                    int nx = cur[0] + dx[d], ny = cur[1] + dy[d];
                    if (nx >= 0 && nx < m && ny >= 0 && ny < n
                        && grid[nx][ny] == 1) {
                        grid[nx][ny] = 2; // now rotten
                        fresh--;
                        q.offer(new int[]{nx, ny});
                    }
                }
            }
        }
        // minutes was incremented one extra time on the final (empty) level
        return fresh == 0 ? minutes - 1 : -1;
    }
}

class Solution {
    public int maxDistance(int[][] grid) {
        int n = grid.length;
        Queue<int[]> q = new ArrayDeque<>();
        // Seed with all land cells
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1) q.offer(new int[]{i, j});
        // All land or all water
        if (q.isEmpty() || q.size() == n * n) return -1;
        int[] dx = {0, 0, 1, -1}, dy = {1, -1, 0, 0};
        int maxDist = -1;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx >= 0 && nx < n && ny >= 0 && ny < n
                    && grid[nx][ny] == 0) {
                    grid[nx][ny] = grid[x][y] + 1; // encode distance from land
                    maxDist = Math.max(maxDist, grid[nx][ny] - 1);
                    q.offer(new int[]{nx, ny});
                }
            }
        }
        return maxDist;
    }
}

class Solution {
    public int ladderLength(String beginWord, String endWord,
                            List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) return 0;
        Queue<String> q = new ArrayDeque<>();
        q.offer(beginWord);
        wordSet.remove(beginWord); // mark as visited
        int steps = 1;
        while (!q.isEmpty()) {
            int size = q.size();
            steps++;
            for (int i = 0; i < size; i++) {
                char[] arr = q.poll().toCharArray();
                for (int j = 0; j < arr.length; j++) {
                    char orig = arr[j];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == orig) continue;
                        arr[j] = c;
                        String next = new String(arr);
                        if (next.equals(endWord)) return steps;
                        if (wordSet.contains(next)) {
                            wordSet.remove(next); // mark visited
                            q.offer(next);
                        }
                    }
                    arr[j] = orig; // restore for next position
                }
            }
        }
        return 0;
    }
}

