// Grid DFS: flood fill (recursive)
void dfsGrid(int[][] grid, int x, int y) {
    int m = grid.length, n = grid[0].length;
    if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y] != 1) return;
    grid[x][y] = -1; // mark visited in-place
    dfsGrid(grid, x+1, y); dfsGrid(grid, x-1, y);
    dfsGrid(grid, x, y+1); dfsGrid(grid, x, y-1);
}

// Directed graph cycle detection (3-color DFS)
// state: 0=unvisited, 1=in current DFS path (gray), 2=fully processed (black)
boolean hasCycle(int u, List<List<Integer>> adj, int[] state) {
    state[u] = 1; // mark gray
    for (int v : adj.get(u)) {
        if (state[v] == 1) return true;  // back edge -> cycle
        if (state[v] == 0 && hasCycle(v, adj, state)) return true;
    }
    state[u] = 2; // mark black
    return false;
}

// Iterative DFS (safe for large grids, avoids StackOverflow)
void dfsIterative(int[][] grid, int startX, int startY) {
    int m = grid.length, n = grid[0].length;
    Deque<int[]> stack = new ArrayDeque<>();
    stack.push(new int[]{startX, startY});
    grid[startX][startY] = -1;
    int[] dx = {0, 0, 1, -1}, dy = {1, -1, 0, 0};
    while (!stack.isEmpty()) {
        int[] cur = stack.pop();
        for (int d = 0; d < 4; d++) {
            int nx = cur[0] + dx[d], ny = cur[1] + dy[d];
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] == 1) {
                grid[nx][ny] = -1;
                stack.push(new int[]{nx, ny});
            }
        }
    }
}

