class Solution {
    private void dfs(int[][] g, int x, int y) {
        int m = g.length, n = g[0].length;
        if (x < 0 || x >= m || y < 0 || y >= n || g[x][y] != 0) return;
        g[x][y] = 1; // sink: mark as water (visited)
        dfs(g, x+1, y); dfs(g, x-1, y);
        dfs(g, x, y+1); dfs(g, x, y-1);
    }

    public int closedIsland(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        // Flood-fill from all border land cells
        for (int i = 0; i < m; i++) {
            dfs(grid, i, 0);
            dfs(grid, i, n-1);
        }
        for (int j = 0; j < n; j++) {
            dfs(grid, 0, j);
            dfs(grid, m-1, j);
        }
        // Count remaining closed islands in the interior
        int count = 0;
        for (int i = 1; i < m-1; i++) {
            for (int j = 1; j < n-1; j++) {
                if (grid[i][j] == 0) {
                    count++;
                    dfs(grid, i, j); // sink this island
                }
            }
        }
        return count;
    }
}

class Solution {
    private void dfs(int[][] g, int x, int y) {
        if (x < 0 || x >= g.length || y < 0 || y >= g[0].length
            || g[x][y] != 1) return;
        g[x][y] = 0; // sink the land
        dfs(g, x+1, y); dfs(g, x-1, y);
        dfs(g, x, y+1); dfs(g, x, y-1);
    }

    public int numEnclaves(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        // Sink all land reachable from the boundary
        for (int i = 0; i < m; i++) { dfs(grid, i, 0); dfs(grid, i, n-1); }
        for (int j = 0; j < n; j++) { dfs(grid, 0, j); dfs(grid, m-1, j); }
        // Count remaining enclosed land cells
        int count = 0;
        for (int[] row : grid) for (int v : row) count += v;
        return count;
    }
}

class Solution {
    private List<List<Integer>> children;
    private int[] informTime;

    public int numOfMinutes(int n, int headID, int[] manager,
                            int[] informTime) {
        this.informTime = informTime;
        children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        for (int i = 0; i < n; i++)
            if (manager[i] != -1) children.get(manager[i]).add(i);
        return dfs(headID);
    }

    // Returns the maximum time to inform all employees in the subtree rooted at u
    private int dfs(int u) {
        int maxChildTime = 0;
        for (int child : children.get(u))
            maxChildTime = Math.max(maxChildTime, dfs(child));
        return informTime[u] + maxChildTime;
    }
}

class Solution {
    // state: 0=unvisited, 1=in current DFS path (unsafe candidate), 2=safe
    private int[] state;
    private int[][] graph;

    public List<Integer> eventualSafeNodes(int[][] graph) {
        this.graph = graph;
        int n = graph.length;
        state = new int[n];
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++)
            if (isSafe(i)) result.add(i);
        // Iterating 0..n-1 guarantees the result is already sorted
        return result;
    }

    private boolean isSafe(int u) {
        if (state[u] == 1) return false; // currently on stack -> cycle
        if (state[u] == 2) return true;  // already confirmed safe
        state[u] = 1; // mark as "being explored"
        for (int v : graph[u]) {
            if (!isSafe(v)) {
                // Do NOT reset state[u] to 0 here - leave it as 1 (unsafe)
                return false;
            }
        }
        state[u] = 2; // all paths from u lead to terminal -> safe
        return true;
    }
}

