List<Integer> kahnTopoSort(int V, List<List<Integer>> adj) {
    int[] inDegree = new int[V];
    for (int u = 0; u < V; u++)
        for (int v : adj.get(u)) inDegree[v]++;

    Queue<Integer> q = new ArrayDeque<>();
    // For lexicographically smallest order, use: new PriorityQueue<>()
    for (int i = 0; i < V; i++)
        if (inDegree[i] == 0) q.offer(i);

    List<Integer> order = new ArrayList<>();
    while (!q.isEmpty()) {
        int u = q.poll();
        order.add(u);
        for (int v : adj.get(u))
            if (--inDegree[v] == 0) q.offer(v);
    }
    // If order.size() != V, a cycle exists
    return order;
}

void dfs(int u, List<List<Integer>> adj, boolean[] visited,
         Deque<Integer> stack) {
    visited[u] = true;
    for (int v : adj.get(u))
        if (!visited[v]) dfs(v, adj, visited, stack);
    stack.push(u); // push after all descendants are processed
}

List<Integer> dfsTopoSort(int V, List<List<Integer>> adj) {
    boolean[] visited = new boolean[V];
    Deque<Integer> stack = new ArrayDeque<>();
    for (int i = 0; i < V; i++)
        if (!visited[i]) dfs(i, adj, visited, stack);
    List<Integer> order = new ArrayList<>();
    while (!stack.isEmpty()) order.add(stack.pop());
    return order;
}

