class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
        int[] inDegree = new int[numCourses];
        for (int[] pre : prerequisites) {
            adj.get(pre[1]).add(pre[0]); // edge: pre[1] -> pre[0]
            inDegree[pre[0]]++;
        }
        Queue<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++)
            if (inDegree[i] == 0) q.offer(i);
        int processed = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            processed++;
            for (int v : adj.get(u))
                if (--inDegree[v] == 0) q.offer(v);
        }
        return processed == numCourses; // true if no cycle
    }
}

class Solution {
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
        int[] inDegree = new int[numCourses];
        for (int[] pre : prerequisites) {
            adj.get(pre[1]).add(pre[0]);
            inDegree[pre[0]]++;
        }
        Queue<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++)
            if (inDegree[i] == 0) q.offer(i);
        int[] order = new int[numCourses];
        int idx = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            order[idx++] = u;
            for (int v : adj.get(u))
                if (--inDegree[v] == 0) q.offer(v);
        }
        return idx == numCourses ? order : new int[0];
    }
}

class Solution {
    public String alienOrder(String[] words) {
        // Initialize in-degree map for every unique character
        Map<Character, Integer> inDegree = new HashMap<>();
        Map<Character, Set<Character>> adj = new HashMap<>();
        for (String w : words) {
            for (char c : w.toCharArray()) {
                inDegree.putIfAbsent(c, 0);
                adj.putIfAbsent(c, new HashSet<>());
            }
        }
        // Extract ordering constraints from adjacent word pairs
        for (int i = 0; i + 1 < words.length; i++) {
            String w1 = words[i], w2 = words[i+1];
            int len = Math.min(w1.length(), w2.length());
            boolean found = false;
            for (int j = 0; j < len; j++) {
                if (w1.charAt(j) != w2.charAt(j)) {
                    char from = w1.charAt(j), to = w2.charAt(j);
                    if (!adj.get(from).contains(to)) {
                        adj.get(from).add(to);
                        inDegree.merge(to, 1, Integer::sum);
                    }
                    found = true;
                    break;
                }
            }
            // w2 is a prefix of w1 but appears later -> invalid
            if (!found && w1.length() > w2.length()) return "";
        }
        // Kahn's topological sort
        Queue<Character> q = new ArrayDeque<>();
        for (Map.Entry<Character, Integer> e : inDegree.entrySet())
            if (e.getValue() == 0) q.offer(e.getKey());
        StringBuilder sb = new StringBuilder();
        while (!q.isEmpty()) {
            char u = q.poll();
            sb.append(u);
            for (char v : adj.get(u)) {
                inDegree.merge(v, -1, Integer::sum);
                if (inDegree.get(v) == 0) q.offer(v);
            }
        }
        return sb.length() == inDegree.size() ? sb.toString() : "";
    }
}

class Solution {
    public boolean sequenceReconstruction(int[] org,
                                          List<List<Integer>> seqs) {
        int n = org.length;
        Map<Integer, Set<Integer>> adj = new HashMap<>();
        Map<Integer, Integer> inDegree = new HashMap<>();
        // Initialize all nodes from org
        for (int v : org) { inDegree.put(v, 0); adj.put(v, new HashSet<>()); }
        // Build constraints from seqs
        for (List<Integer> seq : seqs) {
            for (int v : seq) {
                inDegree.putIfAbsent(v, 0);
                adj.putIfAbsent(v, new HashSet<>());
            }
            for (int i = 0; i + 1 < seq.size(); i++) {
                int u = seq.get(i), v = seq.get(i+1);
                if (!adj.get(u).contains(v)) {
                    adj.get(u).add(v);
                    inDegree.merge(v, 1, Integer::sum);
                }
            }
        }
        if (inDegree.size() != n) return false;
        Queue<Integer> q = new ArrayDeque<>();
        for (Map.Entry<Integer, Integer> e : inDegree.entrySet())
            if (e.getValue() == 0) q.offer(e.getKey());
        int idx = 0;
        while (!q.isEmpty()) {
            if (q.size() > 1) return false; // ambiguous -> not unique
            int u = q.poll();
            if (u != org[idx++]) return false; // wrong order
            for (int v : adj.get(u)) {
                inDegree.merge(v, -1, Integer::sum);
                if (inDegree.get(v) == 0) q.offer(v);
            }
        }
        return idx == n;
    }
}

