class DSU {
    private int[] parent, rank;
    public int components;

    public DSU(int n) {
        parent = new int[n];
        rank = new int[n];
        components = n;
        for (int i = 0; i < n; i++) parent[i] = i; // each node is its own root
    }

    public int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]); // path compression
        return parent[x];
    }

    // Returns true if a union actually happened (x and y were in different sets)
    public boolean union(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false; // already in the same set
        // Union by rank: attach smaller tree under larger tree's root
        if (rank[px] < rank[py]) { int tmp = px; px = py; py = tmp; }
        parent[py] = px;
        if (rank[px] == rank[py]) rank[px]++;
        components--;
        return true;
    }

    public boolean connected(int x, int y) {
        return find(x) == find(y);
    }
}

