class Solution {
    public int makeConnected(int n, int[][] connections) {
        if (connections.length < n - 1) return -1; // not enough cables
        DSU dsu = new DSU(n);
        for (int[] c : connections) dsu.union(c[0], c[1]);
        return dsu.components - 1; // need (components-1) reconnections
    }
}

class Solution {
    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        DSU dsu = new DSU(n + 1); // 1-indexed nodes
        for (int[] e : edges) {
            if (!dsu.union(e[0], e[1])) {
                return e; // union failed -> already connected -> cycle
            }
        }
        return new int[0]; // unreachable for valid input
    }
}

class Solution {
    public List<List<String>> accountsMerge(List<List<String>> accounts) {
        Map<String, Integer> emailToId = new HashMap<>();
        Map<String, String> emailToName = new HashMap<>();
        int id = 0;
        DSU dsu = new DSU(10001); // upper bound on unique emails

        for (List<String> acc : accounts) {
            String name = acc.get(0);
            for (int i = 1; i < acc.size(); i++) {
                String email = acc.get(i);
                emailToName.put(email, name);
                emailToId.putIfAbsent(email, id++);
                // Union this email with the first email of this account
                dsu.union(emailToId.get(acc.get(1)),
                          emailToId.get(email));
            }
        }
        // Group emails by their DSU root
        Map<Integer, List<String>> groups = new HashMap<>();
        for (String email : emailToId.keySet()) {
            int root = dsu.find(emailToId.get(email));
            groups.computeIfAbsent(root, k -> new ArrayList<>())
                  .add(email);
        }
        List<List<String>> result = new ArrayList<>();
        for (List<String> emails : groups.values()) {
            Collections.sort(emails);
            List<String> merged = new ArrayList<>();
            merged.add(emailToName.get(emails.get(0))); // prepend name
            merged.addAll(emails);
            result.add(merged);
        }
        return result;
    }
}

class Solution {
    public boolean equationsPossible(String[] equations) {
        DSU dsu = new DSU(26); // a=0, b=1, ..., z=25
        // First pass: union all equality pairs
        for (String eq : equations) {
            if (eq.charAt(1) == '=') { // eq is "a==b"
                dsu.union(eq.charAt(0) - 'a', eq.charAt(3) - 'a');
            }
        }
        // Second pass: verify all inequality pairs are in different sets
        for (String eq : equations) {
            if (eq.charAt(1) == '!') { // eq is "a!=b"
                if (dsu.connected(eq.charAt(0) - 'a', eq.charAt(3) - 'a')) {
                    return false; // contradiction: a==b AND a!=b
                }
            }
        }
        return true;
    }
}

