// adj[u] = list of int[]{v, weight}
int[] dijkstra(int src, int n, List<List<int[]>> adj) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[src] = 0;
    // Min-heap: {distance, node}
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
    pq.offer(new int[]{0, src});
    while (!pq.isEmpty()) {
        int[] cur = pq.poll();
        int d = cur[0], u = cur[1];
        if (d > dist[u]) continue; // stale entry - skip
        for (int[] edge : adj.get(u)) {
            int v = edge[0], w = edge[1];
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.offer(new int[]{dist[v], v});
            }
        }
    }
    return dist;
}

// edges[i] = {u, v, weight}
int[] bellmanFord(int src, int n, int[][] edges) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[src] = 0;
    for (int i = 0; i < n - 1; i++) { // V-1 relaxation rounds
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            if (dist[u] != Integer.MAX_VALUE && dist[u] + w < dist[v])
                dist[v] = dist[u] + w;
        }
    }
    // Optional: V-th pass checks for negative cycle
    // for (int[] e : edges) if (dist[e[0]] + e[2] < dist[e[1]]) -> negative cycle
    return dist;
}

// dist[i][j] pre-initialized: 0 for i==j, edge weight for direct edge, INF otherwise
void floydWarshall(int[][] dist, int n) {
    final int INF = (int) 1e8; // use 1e8 to avoid overflow on addition
    for (int k = 0; k < n; k++)
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (dist[i][k] < INF && dist[k][j] < INF)
                    dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
}

// edges[i] = {weight, u, v} - weight in position 0 for easy sorting
int kruskalMST(int n, int[][] edges) {
    Arrays.sort(edges, (a, b) -> a[0] - b[0]); // sort by weight
    DSU dsu = new DSU(n);
    int totalCost = 0;
    for (int[] e : edges) {
        if (dsu.union(e[1], e[2])) { // no cycle formed
            totalCost += e[0];
        }
    }
    return totalCost;
}

